  void loop(int[] xs) {
    int x = xs.length;
    Runnable r = () -> {
      for (int v : xs) {
        if (v > 0 || v < -5) {
          continue;
        }
      }
    };
    try {
      r.run();
    } catch (RuntimeException e) {
      do {
        x = x > 0 ? x - 1 : 0;
      } while (x != 0);
    }
  }

  record Point(int x) {
    Point {
      if (x < 0) throw new IllegalArgumentException();
    }
  }
}

